const cfg = $('Config — Łazikomat').first().json;
const now = new Date();
const toBool = (v) => ['true','1','yes','tak','active'].includes(String(v ?? '').trim().toLowerCase());
const normalizePlatform = (v) => {
  const value = String(v || 'INSTAGRAM').trim().toUpperCase();
  if (['IG','INSTAGRAM'].includes(value)) return 'INSTAGRAM';
  if (['FB','FACEBOOK'].includes(value)) return 'FACEBOOK';
  return '';
};
const cleanHandle = (row, platform) => {
  const raw = String(row.Username || '').trim().replace(/^@/, '');
  if (raw && !raw.includes('UZUPEŁNIJ')) return raw;
  try {
    const url = new URL(String(row.Profile_URL || '').trim());
    const parts = url.pathname.split('/').filter(Boolean);
    if (platform === 'FACEBOOK' && parts[0] === 'pages' && parts.length >= 3) return parts[2];
    return parts[0] || '';
  } catch {
    return '';
  }
};
const profileUrl = (row, platform, handle) => {
  const supplied = String(row.Profile_URL || '').trim();
  if (supplied.startsWith('http://') || supplied.startsWith('https://')) return supplied;
  return platform === 'FACEBOOK'
    ? `https://www.facebook.com/${handle}/`
    : `https://www.instagram.com/${handle}/`;
};

const candidates = items
  .map(i => i.json)
  .map(row => {
    const Platform = normalizePlatform(row.Platform);
    const Username = cleanHandle(row, Platform);
    return {
      ...row,
      Platform,
      Username,
      Profile_URL: profileUrl(row, Platform, Username),
    };
  })
  .filter(r => toBool(r.Active))
  .filter(r => ['INSTAGRAM','FACEBOOK'].includes(r.Platform))
  .filter(r => r.Username)
  .filter(r => {
    if (!r.Cooldown_Until) return true;
    const d = new Date(r.Cooldown_Until);
    return Number.isNaN(d.getTime()) || d <= now;
  })
  .sort((a,b) => {
    const pa = Number(a.Priority || 0);
    const pb = Number(b.Priority || 0);
    if (pb !== pa) return pb - pa;
    const la = a.Last_Selected_At ? new Date(a.Last_Selected_At).getTime() : 0;
    const lb = b.Last_Selected_At ? new Date(b.Last_Selected_At).getTime() : 0;
    return la - lb;
  })
  .slice(0, Number(cfg.dailyLimit || 30));

if (!candidates.length) {
  return [{json: {skip: true, reason: 'Brak aktywnych profili Facebook/Instagram poza cooldownem.'}}];
}

const instagramFields = (username) =>
  `business_discovery.username(${username}){username,name,profile_picture_url,followers_count,media.limit(1){id,caption,permalink,timestamp,media_type}}`;

const facebookFields =
  'id,name,link,followers_count,fan_count,posts.limit(1){id,message,permalink_url,created_time}';

const batch = candidates.map(target => {
  if (target.Platform === 'FACEBOOK') {
    return {
      method: 'GET',
      relative_url: `${encodeURIComponent(target.Username)}?fields=${encodeURIComponent(facebookFields)}`
    };
  }
  return {
    method: 'GET',
    relative_url: `${cfg.igUserId}?fields=${encodeURIComponent(instagramFields(target.Username))}`
  };
});

return [{
  json: {
    skip: false,
    selectedAt: now.toISOString(),
    candidates,
    batch
  }
}];

const selected = $('Select up to 30 + Build Meta Batch').first().json;

// n8n może zwrócić batch Meta na trzy sposoby:
// 1. każdy element tablicy jako osobny item,
// 2. jeden item będący tablicą,
// 3. jeden item z tablicą w polu body.
const incoming = $input.all().map(item => item.json);

let responses;
if (incoming.length === 1 && Array.isArray(incoming[0])) {
  responses = incoming[0];
} else if (incoming.length === 1 && Array.isArray(incoming[0]?.body)) {
  responses = incoming[0].body;
} else {
  responses = incoming;
}

if (!Array.isArray(responses)) {
  throw new Error(
    `Meta batch returned unexpected payload: ${JSON.stringify(incoming).slice(0, 1200)}`
  );
}

function parseBody(response) {
  const rawBody = response?.body ?? response ?? {};

  if (typeof rawBody === 'string') {
    try {
      return JSON.parse(rawBody);
    } catch {
      return {
        error: {
          message: `Nie udało się sparsować body Meta: ${rawBody.slice(0, 500)}`
        }
      };
    }
  }

  return rawBody && typeof rawBody === 'object' ? rawBody : {};
}

const rows = selected.candidates.map((target, idx) => {
  const response = responses[idx] || {};
  const body = parseBody(response);
  const error = body.error || {};

  const metaCode = Number(
    response.code ??
    error.code ??
    0
  );

  const metaError =
    String(error.message || '').trim() ||
    (metaCode >= 400 ? `Meta subrequest HTTP ${metaCode}` : '');

  const common = {
    ...target,
    metaCode,
    metaError,
    metaErrorType: String(error.type || ''),
    metaErrorSubcode: Number(error.error_subcode || 0),
    metaTraceId: String(error.fbtrace_id || ''),
  };

  if (target.Platform === 'FACEBOOK') {
    const post = body.posts?.data?.[0] || {};

    return {
      ...common,
      Profile_URL:
        body.link ||
        target.Profile_URL ||
        `https://www.facebook.com/${target.Username}/`,
      Latest_Post_URL:
        post.permalink_url ||
        target.Latest_Post_URL ||
        '',
      Latest_Post_Caption: post.message || '',
      Latest_Post_Timestamp: post.created_time || '',
      Followers_Count:
        body.followers_count ||
        body.fan_count ||
        '',
      Profile_Name: body.name || '',
    };
  }

  const discovery = body.business_discovery || {};
  const media = discovery.media?.data?.[0] || {};

  return {
    ...common,
    Profile_URL:
      target.Profile_URL ||
      `https://www.instagram.com/${target.Username}/`,
    Latest_Post_URL:
      media.permalink ||
      target.Latest_Post_URL ||
      '',
    Latest_Post_Caption: media.caption || '',
    Latest_Post_Timestamp: media.timestamp || '',
    Followers_Count: discovery.followers_count || '',
    Profile_Name: discovery.name || '',
  };
});

return [{
  json: {
    selectedAt: selected.selectedAt,
    responseCount: responses.length,
    candidateCount: selected.candidates.length,
    rows
  }
}];

const rows = $json.rows || [];
const payload = rows.map((r, i) => ({
  index: i,
  platform: r.Platform,
  username: r.Username,
  category: r.Category || '',
  caption: String(r.Latest_Post_Caption || '').slice(0, 1200),
  url: r.Latest_Post_URL || '',
  error: r.metaError || ''
}));
const prompt = `You are the organic community assistant for VIRYA, a Polish modern/alternative metal band.
For each Facebook or Instagram item, propose ONE brief, authentic comment that a real band member could leave manually.
Rules:
- use the language of the source caption when obvious; otherwise English;
- 4-18 words;
- reference a concrete detail from the caption;
- no generic "great post", no spam, no sales pitch, no asking for follows;
- no emojis unless the source tone clearly uses them;
- if the item has an API error, no caption, or no post URL, return an empty comment.
Return ONLY a valid JSON array of objects:
[{"index":0,"comment":"...","reason":"short internal reason"}]

INPUT:
${JSON.stringify(payload)}`;
return [{json: {...$json, geminiRequest: {
  contents: [{role: 'user', parts: [{text: prompt}]}],
  generationConfig: {
    temperature: 0.35,
    responseMimeType: 'application/json'
  }
}}}];

const cfg = $('Config — Łazikomat').first().json;
const source = $('Build Gemini Comment Prompt').first().json;
const response = items[0]?.json || {};
const text = response.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '[]';
let suggestions = [];
try {
  suggestions = JSON.parse(text.replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch {
  suggestions = [];
}
const byIndex = new Map((Array.isArray(suggestions) ? suggestions : []).map(x => [Number(x.index), x]));
const now = new Date(source.selectedAt || Date.now());
const review = new Date(now);
review.setDate(review.getDate() + Number(cfg.cooldownDays || 7));
const stamp = now.toISOString().replace(/[-:.TZ]/g,'').slice(0,14);

const logs = [];
const targets = [];
source.rows.forEach((row, index) => {
  const suggestion = byIndex.get(index) || {};
  const platform = String(row.Platform || 'INSTAGRAM').toUpperCase();
  const hasPost = Boolean(row.Latest_Post_URL);
  const apiOk = !row.metaError;
  const status = row.metaError ? 'API_ERROR' : (hasPost ? 'QUEUED' : 'PROFILE_ONLY');
  const profileUrl = row.Profile_URL || (
    platform === 'FACEBOOK'
      ? `https://www.facebook.com/${String(row.Username).replace(/^@/,'')}/`
      : `https://www.instagram.com/${String(row.Username).replace(/^@/,'')}/`
  );
  const suggestedComment = hasPost ? String(suggestion.comment || '') : '';
  const initialAction = hasPost
    ? 'MANUAL_FOLLOW_LIKE_COMMENT'
    : 'MANUAL_FOLLOW_PROFILE';

  logs.push({
    Event_ID: `ENG-${stamp}-${String(index+1).padStart(2,'0')}`,
    Selected_At: now.toISOString(),
    Username: row.Username,
    Profile_URL: profileUrl,
    Platform: platform,
    Suggested_Action: initialAction,
    Latest_Post_URL: row.Latest_Post_URL || '',
    Suggested_Comment: suggestedComment,
    Completed_At: '',
    Review_After: review.toISOString(),
    Review_Status: 'PENDING',
    Outcome: '',
    Source: row.Source || 'ENGAGEMENT_TARGETS',
    Notes: [
      apiOk ? '' : `META_API: ${row.metaError}`,
      String(suggestion.reason || ''),
      '7D_ACTION=UNFOLLOW_OR_KEEP'
    ].filter(Boolean).join(' | ')
  });

  targets.push({
    Active: row.Active,
    Username: row.Username,
    Profile_URL: profileUrl,
    Platform: platform,
    Category: row.Category || '',
    Priority: row.Priority || '',
    Source: row.Source || '',
    Last_Selected_At: now.toISOString(),
    Cooldown_Until: review.toISOString(),
    Interaction_Status: status,
    Latest_Post_URL: row.Latest_Post_URL || '',
    Latest_Post_Caption: row.Latest_Post_Caption || '',
    Suggested_Comment: suggestedComment,
    Notes: row.metaError || row.Notes || ''
  });
});
return [{json:{logs, targets}}];

const logs = $('Prepare Sheet Rows').first().json.logs || [];
const usable = logs.filter(row => row.Profile_URL);
const platformLabel = platform => platform === 'FACEBOOK' ? 'FB' : 'IG';
const chunks = [];

for (let offset = 0; offset < usable.length; offset += 8) {
  const block = usable.slice(offset, offset + 8).map((row, localIndex) => {
    const number = offset + localIndex + 1;
    const post = row.Latest_Post_URL ? `\n📰 Post: ${row.Latest_Post_URL}` : '';
    const comment = row.Suggested_Comment ? `\n💬 Komentarz: ${row.Suggested_Comment}` : '';
    return [
      `**${number}. [${platformLabel(row.Platform)}] @${String(row.Username).replace(/^@/,'')}**`,
      `👤 Profil: ${row.Profile_URL}`,
      `➡️ Teraz: ręcznie FOLLOW${row.Latest_Post_URL ? ' + LIKE/COMMENT, jeśli pasuje' : ''}`,
      post,
      comment,
      `🆔 ${row.Event_ID}`,
    ].filter(Boolean).join('\n');
  }).join('\n\n');

  chunks.push({
    message:
      `## VIRYA — Łazikomat FB + IG ${offset + 1}-${Math.min(offset + 8, usable.length)}/${usable.length}\n` +
      `To jest ręczna kolejka. Obserwuj tylko sensowne profile i reaguj autentycznie.\n` +
      `Za 7 dni workflow przypomni dokładnie tę samą paczkę do decyzji **UNFOLLOW / KEEP**.\n\n${block}`
  });
}
return chunks.map(chunk => ({json: chunk}));

const now = new Date();
const normalizePlatform = value => {
  const platform = String(value || '').toUpperCase();
  return ['FB','FACEBOOK'].includes(platform) ? 'FACEBOOK' : 'INSTAGRAM';
};
const formatDate = value => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value || '');
  return new Intl.DateTimeFormat('pl-PL', {
    timeZone: 'Europe/Warsaw',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  }).format(date);
};

const due = items
  .map(item => item.json)
  .filter(row => String(row.Review_Status || '').toUpperCase() === 'PENDING')
  .filter(row => {
    if (!row.Review_After) return false;
    const date = new Date(row.Review_After);
    return !Number.isNaN(date.getTime()) && date <= now;
  })
  .sort((a,b) => new Date(a.Selected_At || 0) - new Date(b.Selected_At || 0));

if (!due.length) return [];

const chunks = [];
for (let offset = 0; offset < due.length; offset += 8) {
  const text = due.slice(offset, offset + 8).map((row, localIndex) => {
    const platform = normalizePlatform(row.Platform);
    const platformLabel = platform === 'FACEBOOK' ? 'FB' : 'IG';
    const unfollowText = platform === 'FACEBOOK'
      ? 'Przestań obserwować stronę'
      : 'Przestań obserwować profil';
    const originalAction = String(row.Suggested_Action || '').includes('LIKE_COMMENT')
      ? 'FOLLOW + ewentualny LIKE/COMMENT'
      : 'FOLLOW profilu';
    const post = row.Latest_Post_URL ? `\n📰 Wcześniejszy post: ${row.Latest_Post_URL}` : '';
    const comment = row.Suggested_Comment ? `\n💬 Wcześniejszy komentarz: ${row.Suggested_Comment}` : '';

    return [
      `**${offset + localIndex + 1}. [${platformLabel}] @${String(row.Username || '').replace(/^@/,'')}**`,
      `📤 Wysłane wcześniej: ${formatDate(row.Selected_At)}`,
      `➡️ Wtedy: ${originalAction}`,
      `👤 Profil: ${row.Profile_URL || ''}`,
      post,
      comment,
      `⏰ Teraz: **${unfollowText} (UNFOLLOWED)** albo świadomie zostaw (**KEEP**)`,
      `🆔 ${row.Event_ID || ''}`,
      `W ENGAGEMENT_LOG ustaw Review_Status → UNFOLLOWED / KEEP.`,
    ].filter(Boolean).join('\n');
  }).join('\n\n');

  chunks.push({
    message:
      `## VIRYA — po 7 dniach: odsubskrybuj albo zostaw\n` +
      `Poniżej dokładnie to, co Łazikomat wysłał tydzień wcześniej na Facebooku i Instagramie.\n` +
      `To nie wykonuje automatycznego unfollow — decyzja i kliknięcie są ręczne.\n\n${text}`
  });
}
return chunks.map(chunk => ({json: chunk}));
